<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\{Order,Payment}; use App\Services\OrderService; use Illuminate\Http\Request;
class OrderController extends Controller { public function __construct(private OrderService $service){} public function index(Request $r){return Order::with('items.product','payments')->where('user_id',$r->user()->id)->latest()->paginate(10);} public function show(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,403);return $order->load('items.product','payments','preInvoice');} public function store(Request $r){$d=$r->validate(['payment_method'=>'required|in:bank_transfer,check,online','shipping_address'=>'required|array','shipping_address.province'=>'required','shipping_address.city'=>'required','shipping_address.address'=>'required','shipping_address.postal_code'=>'nullable','shipping_address.phone'=>'required']);return response()->json($this->service->create($r->user()->id,$d),201);} public function uploadPayment(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,403);$d=$r->validate(['receipt'=>'required|image|max:5120','method'=>'required|in:bank_transfer,check']);$payment=$order->payments()->latest()->first();$path=$r->file('receipt')->store('payments','public');$payment->update(['receipt_path'=>$path,'status'=>'waiting_verification','method'=>$d['method']]);$order->update(['status'=>$d['method']==='check'?'waiting_for_check_verification':'waiting_for_verification']);return ['message'=>'مدرک پرداخت ارسال شد.','order'=>$order->fresh()];} }
